        public static bool IsLand(float lat, float lon)
        {
            if (_landMask == null) _landMask = Convert.FromBase64String(LandMaskBase64);
            int x = (int)Math.Floor(lon + 180f);
            int y = (int)Math.Floor(lat + 90f);
            x = (x % 360 + 360) % 360;
            if (y < 0) y = 0; else if (y > 179) y = 179;
            int idx = y * 360 + x;
            return (_landMask[idx / 8] & (1 << (idx % 8))) != 0;
        }

